async () => {
 const aid='b03e6ea242724c05eb97eb732cceb21d',wid='9b7d9c86f72e4af38303e3f9e63ee3c9',name='bee-validation-20260909',old='1c29a7a3-b0f3-441d-8089-8afddaf9bece',expected='4a0be14b596068c32a6aab5f188abaa8ebcf4430721bd90af4d89cda7a651eee';
 let phase='preflight',version=null;
 const assert=(x,m)=>{if(!x)throw Error(m)};
 async function api(method,path,body){const r=await fetch('https://api.cloudflare.com/client/v4/accounts/'+aid+path,{method,redirect:'manual',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const j=await r.json();assert(r.ok&&j.success,'provider '+method+' '+r.status);return j.result;}
 const canonical=x=>JSON.stringify([...x].sort((a,b)=>a.name.localeCompare(b.name)));
 async function hash(m){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',Uint8Array.from(atob(m.content_base64),c=>c.charCodeAt(0)))),c=>c.toString(16).padStart(2,'0')).join('');}
 async function boundaries(){const w=await api('GET','/workers/workers/'+wid),s=await api('GET','/workers/scripts/'+name+'/subdomain');assert(w.observability?.enabled===false&&w.observability?.logs?.enabled===false&&w.observability?.traces?.enabled===false&&w.logpush===false,'logs');assert(s.enabled===true&&s.previews_enabled===false,'ingress');return JSON.stringify({observability:w.observability,logpush:w.logpush,subdomain:s});}
 try {
  assert(accountId===aid,'account');
  const domain=(await api('GET','/access/organizations')).auth_domain;assert(domain==='klappy.cloudflareaccess.com','team domain');
  const bounds=await boundaries(),prod=JSON.stringify(await api('GET','/workers/scripts/bee-ai-auth-mcp/deployments'));
  const apps=JSON.stringify(await api('GET','/access/apps'));
  const policies={};for(const id of ['8fc54e03-24c8-4c02-9376-7c639a3ca94e','f5c6bb74-2b83-441a-a316-08de4c68743a','5ae63959-05d5-45a7-a9bd-237c271245c0'])policies[id]=JSON.stringify(await api('GET','/access/apps/'+id+'/policies'));
  const d=await api('GET','/workers/scripts/'+name+'/deployments');assert(d.deployments[0].versions.length===1&&d.deployments[0].versions[0].version_id===old,'active');
  const v=await api('GET','/workers/workers/'+wid+'/versions/'+old+'?include=modules');assert(v.modules.length===1&&await hash(v.modules[0])===expected,'source');
  assert(v.bindings.find(b=>b.name==='ACCESS_TEAM_DOMAIN')?.text==='','old issuer');
  for(const n of ['ACCESS_AUD','VALIDATION_STARTS_AT','VALIDATION_EXPIRES_AT'])assert(v.bindings.find(b=>b.name===n)?.text==='','data gate');assert(v.bindings.every(b=>b.type!=='secret_text'),'secrets');
  const body={};for(const k of ['assets','bindings','cache_options','compatibility_date','compatibility_flags','containers','limits','main_module','migration_tag','modules','package_dependencies','placement','usage_model'])if(v[k]!==undefined)body[k]=v[k];
  body.exports={...(v.exports||{}),BeeBridge:{type:'durable-object',storage:'sqlite',container:'BeeBridge'}};body.containers=body.containers.map(c=>c.class_name==='BeeBridge'?{...c,name:'BeeBridge'}:c);
  body.bindings=v.bindings.map(b=>b.name==='ACCESS_TEAM_DOMAIN'?{...b,text:domain}:b);body.annotations={'workers/message':'Repair staging Access issuer binding; unchanged source and closed data gate.'};
  phase='upload';version=(await api('POST','/workers/workers/'+wid+'/versions?deploy=false',body)).id;
  const uploaded=await api('GET','/workers/workers/'+wid+'/versions/'+version+'?include=modules');assert(uploaded.modules.length===1&&await hash(uploaded.modules[0])===expected,'upload source');assert(canonical(uploaded.bindings)===canonical(body.bindings),'upload bindings');assert((await api('GET','/workers/scripts/'+name+'/deployments')).deployments[0].versions[0].version_id===old,'upload deployment effect');
  phase='deploy';await api('POST','/workers/scripts/'+name+'/deployments',{strategy:'percentage',versions:[{version_id:version,percentage:100}],annotations:{'workers/message':'Repair staging owner JWT issuer configuration only.'}});
  phase='readback';const after=await api('GET','/workers/scripts/'+name+'/deployments');assert(after.deployments[0].versions.length===1&&after.deployments[0].versions[0].version_id===version&&after.deployments[0].versions[0].percentage===100,'deployment');
  assert(await boundaries()===bounds,'boundaries');assert(JSON.stringify(await api('GET','/workers/scripts/bee-ai-auth-mcp/deployments'))===prod,'production changed');assert(JSON.stringify(await api('GET','/access/apps'))===apps,'apps changed');for(const id of Object.keys(policies))assert(JSON.stringify(await api('GET','/access/apps/'+id+'/policies'))===policies[id],'policies changed');
  const settings=await api('GET','/workers/scripts/'+name+'/settings');assert(canonical(settings.bindings)===canonical(body.bindings),'effective bindings');
  return {accepted:true,observed:new Date().toISOString(),phase,previous_version:old,version,deployment:after.deployments[0].id,module_sha256:expected,source_unchanged:true,only_binding_changed:'ACCESS_TEAM_DOMAIN',domain,access_apps_policies_unchanged:true,production_unchanged:true,data_gate_closed:true,logging_disabled:true,ingress_enabled:true,preview_disabled:true,secrets_absent:true};
 }catch(e){return {accepted:false,phase,version,error:e.message};}
}

function transformStaging(src) {
  const marker = 'var validation_default = {\n  async fetch(request, env2, ctx) {\n';
  if(src.split(marker).length !== 2) throw Error('entrypoint mismatch');
  return src.replace(marker, marker + `    if (["GET", "HEAD"].includes(request.method)) {
      const assetHeaders = new Headers(request.headers);
      assetHeaders.delete("If-None-Match");
      const candidate = await embeddedAssets.fetch(new Request(request, { headers: assetHeaders }));
      if (candidate.status !== 404 && candidate.status !== 405) {
        const identity = await verifyAccessJwt(request, { ...env2, ACCESS_AUD: env2.STAGING_PREVIEW_AUD });
        if (!identity) return validationClosed();
        const headers = new Headers(candidate.headers);
        headers.set("Cache-Control", "private, no-store");
        headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
        headers.set("Referrer-Policy", "no-referrer");
        if (headers.get("Content-Type")?.includes("text/html")) { headers.delete("Content-Length"); headers.delete("ETag"); }
        if (candidate.status === 200 && request.method === "GET" && headers.get("Content-Type")?.includes("text/html")) {
          const body = (await candidate.text()).replaceAll("https://bee.klappy.dev", new URL(request.url).origin);
          headers.delete("Content-Length"); headers.delete("ETag");
          return new Response(body, { status: 200, headers });
        }
        return new Response(candidate.body, { status: candidate.status, headers });
      }
    }
`);
}

import { test, expect, vi, afterEach } from 'vitest';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';
import { SignJWT, exportJWK, generateKeyPair } from 'jose';
import { verifyAccessJwt, __resetJwksCacheForTests } from '../src/access';

const original = { ACCESS_TEAM_DOMAIN: '', ACCESS_AUD: '', STAGING_PREVIEW_AUD: '11479aab4d4f4d70aec0d82b1c04bbc1972e179a9cadee257c483f5fbebb2a75', VALIDATION_STARTS_AT: '', VALIDATION_EXPIRES_AT: '' };
const corrected = { ...original, ACCESS_TEAM_DOMAIN: 'klappy.cloudflareaccess.com' };
afterEach(() => { vi.unstubAllGlobals(); __resetJwksCacheForTests(); });
test('actual staging transform and real verifier: old provider config fails, repaired issuer succeeds, invalid tokens fail', async () => {
  const keys = await generateKeyPair('RS256');
  const jwk = { ...await exportJWK(keys.publicKey), kid: 'local-only', alg: 'RS256' };
  let certReads = 0;
  vi.stubGlobal('fetch', async (url: any) => {
    expect(String(url)).toBe('https://klappy.cloudflareaccess.com/cdn-cgi/access/certs');
    certReads++;
    return new Response(JSON.stringify({keys:[jwk]}), {headers:{'Content-Type':'application/json'}});
  });
  const mint = (aud = original.STAGING_PREVIEW_AUD, iss = 'https://klappy.cloudflareaccess.com') => new SignJWT({email:'synthetic@example.invalid'}).setProtectedHeader({alg:'RS256',kid:'local-only'}).setIssuer(iss).setAudience(aud).setIssuedAt().setExpirationTime('5m').sign(keys.privateKey);
  const transform = vm.runInNewContext(readFileSync('../../transform-staging.js','utf8')+';transformStaging');
  const source = transform('var validation_default = {\n  async fetch(request, env2, ctx) {\n return validationClosed();\n}};');
  const run = vm.runInNewContext(source+';validation_default.fetch', {Request,Response,Headers,URL,verifyAccessJwt,validationClosed:()=>new Response('closed',{status:503}),embeddedAssets:{fetch:async(r:Request)=>new URL(r.url).pathname==='/'?new Response('homepage',{headers:{'Content-Type':'text/html'}}):new Response(null,{status:404})}});
  const req = (token?:string,path='/') => new Request('https://bee-validation-20260909.klappy.workers.dev'+path,{headers:token?{'Cf-Access-Jwt-Assertion':token}:{}});
  const valid = await mint();
  expect((await run(req(valid),original,{})).status).toBe(503);
  expect(certReads).toBe(0);
  const success = await run(req(valid),corrected,{});
  expect(success.status).toBe(200);
  expect(await success.text()).toBe('homepage');
  expect(certReads).toBe(1);
  const imposter = await generateKeyPair('RS256');
  const badSignature = await new SignJWT({email:'synthetic@example.invalid'}).setProtectedHeader({alg:'RS256',kid:'local-only'}).setIssuer('https://klappy.cloudflareaccess.com').setAudience(original.STAGING_PREVIEW_AUD).setExpirationTime('5m').sign(imposter.privateKey);
  for (const token of [undefined,'malformed',badSignature,await mint('wrong-aud'),await mint(original.STAGING_PREVIEW_AUD,'https://wrong.example')]) expect((await run(req(token),corrected,{})).status).toBe(503);
  expect((await run(req(valid,'/mcp'),corrected,{})).status).toBe(503);
});
